import React, { useState } from 'react';
import { Calendar, momentLocalizer } from 'react-big-calendar';
import moment from 'moment';
import 'react-big-calendar/lib/css/react-big-calendar.css';
import './AttendancePage.css'; // For custom styling

// Setup the localizer by providing the moment object
const localizer = momentLocalizer(moment);

// Mock "events" for the calendar. In a real app, this would be your time log data.
const mockEvents = [
    // These events would be generated from your time log data
    {
        title: '95% Present',
        start: new Date(2025, 9, 20), // Month is 0-indexed, so 9 = October
        end: new Date(2025, 9, 20),
        allDay: true,
        resource: { status: 'good' }
    },
    {
        title: '8 Absent',
        start: new Date(2025, 9, 21),
        end: new Date(2025, 9, 21),
        allDay: true,
        resource: { status: 'bad' }
    },
];

// Mock data for the daily employee list
const mockDailyLog = [
  { id: 1, name: 'Dr. Anjali Rao', clockIn: '09:05 AM', clockOut: '05:00 PM', status: 'Present'},
  { id: 2, name: 'Prof. Vikram Kumar', clockIn: '09:35 AM', clockOut: '05:10 PM', status: 'Discrepancy'},
  { id: 3, name: 'Dr. Priya Mehta', clockIn: '--:--', clockOut: '--:--', status: 'Absent'},
];


const AttendancePage = () => {
  const [events, setEvents] = useState(mockEvents);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [view, setView] = useState('month'); // 'month', 'week', 'day'

  // This function would be called when the user selects a date or changes view
  const handleNavigate = (date, view) => {
    console.log("Navigated to date:", date);
    setSelectedDate(date);
    // Here you would fetch the data for the new date/view from your backend
  };

  return (
    <div className="p-8 flex flex-col h-full">
      <div className="bg-card-light dark:bg-card-dark rounded-xl shadow-md flex-1 flex flex-col">
        {/* Calendar Header with View Toggles */}
        <div className="p-4 border-b border-border-light flex justify-between items-center">
          <h2 className="text-xl font-semibold text-text-light dark:text-text-dark">
            {moment(selectedDate).format('MMMM YYYY')}
          </h2>
          {/* This is where the view toggles would go if you use the built-in toolbar */}
        </div>

        {/* Main Calendar View */}
        <div className="flex-grow p-4">
          <Calendar
            localizer={localizer}
            events={events}
            startAccessor="start"
            endAccessor="end"
            style={{ height: '100%' }}
            onNavigate={handleNavigate}
            view={view}
            onView={setView}
            date={selectedDate}
            eventPropGetter={(event) => ({
                className: `event-${event.resource.status}`
            })}
          />
        </div>
      </div>

      {/* Daily Details List - Shown when in 'day' view or a day is clicked */}
      <div className="mt-8 bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-sm">
        <h3 className="text-lg font-semibold mb-4">Attendance for {moment(selectedDate).format('MMMM Do, YYYY')}</h3>
        <DailyAttendanceTable logs={mockDailyLog} />
      </div>
    </div>
  );
};

// Helper component for the daily log table
const DailyAttendanceTable = ({ logs }) => (
  <div className="overflow-x-auto">
    <table className="w-full text-sm text-left">
      <thead className="text-xs uppercase bg-background-light">
        <tr>
          <th className="px-6 py-3">Employee</th>
          <th className="px-6 py-3">Clock In</th>
          <th className="px-6 py-3">Clock Out</th>
          <th className="px-6 py-3">Status</th>
        </tr>
      </thead>
      <tbody>
        {logs.map(log => (
          <tr key={log.id} className="border-b hover:bg-gray-50">
            <td className="px-6 py-4 font-medium">{log.name}</td>
            <td className="px-6 py-4">{log.clockIn}</td>
            <td className="px-6 py-4">{log.clockOut}</td>
            <td className="px-6 py-4">{log.status}</td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

export default AttendancePage;
